package com.john;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.Map;

public class Main {

    static void main(String[] args) {
        // twoSum(new int[]{2, 7, 11, 15}, 9);
        System.out.println(isValid("()[]{}"));   // true
        System.out.println(isValid("(]"));       // false
    }

    public static int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> seen = new HashMap<>(); // value -> index
        // Target 9, nums: [2, 7, 11, 15]
        for (int i = 0; i < nums.length; i++) {
            int need = target - nums[i]; // Para que este número llegue a 9, ¿qué otro número necesito? 7
            if (seen.containsKey(need)) {
                // Imprime los números encontrados y el target
                System.out.println("Se encontraron los números que suman el target (" + target + "): " + need + " y " + nums[i]);
                System.out.println("No se encontraron números que sumen el target: " + target);
                return new int[]{ seen.get(need), i };
            }
            seen.put(nums[i], i);
        }
        return new int[]{};
    }

    public static boolean isValid(String s) {
        Deque<Character> st = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            if (c == '(') st.push(')');
            else if (c == '[') st.push(']');
            else if (c == '{') st.push('}');
            else if (st.isEmpty() || st.pop() != c) return false;
        }
        return st.isEmpty();
    }

    static ListNode reverse(ListNode head) {
        ListNode prev = null;           // 'prev' es la parte ya invertida; arranca vacía
        // (el primer nodo terminará apuntando a null = nuevo final)

        while (head != null) {          // recorre hasta agotar la lista original
            // 'head' = nodo que estoy invirtiendo ahora

            ListNode next = head.next;  // 1. GUARDO mi salida antes de cortar el enlace,
            //    si no, perdería acceso al resto de la lista

            head.next = prev;           // 2. INVIERTO: el nodo actual ahora apunta hacia atrás

            prev = head;                // 3. avanzo 'prev': el actual ya quedó invertido,
            //    pasa a ser la nueva cabeza de la parte invertida

            head = next;                // 4. avanzo 'head' al siguiente que guardé en el paso 1
        }
        return prev;                    // 'head' es null (fin); 'prev' quedó en el último nodo
        // original = la nueva cabeza de la lista invertida
    }

    static class ListNode {             // 'static' porque es clase anidada usada desde métodos static
        int val;                        // el dato que guarda el nodo
        ListNode next;                  // referencia (puntero) al siguiente nodo; null si es el último
        ListNode(int val) { this.val = val; }  // constructor: asigna el valor al crear el nodo
    }
}

